using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.QuadraticForms;

internal sealed class ParallelogramConstructionDocument : IScribeDocumentDefinition
{
    private static readonly LibraryNoteRef Source =
        LibraryNoteRef.Create("D5/L/ArithUnits/tauceti2026canonicalheight");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "An integer quadratic map from the parallelogram law.",
        H("An integer quadratic map from the parallelogram law"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("parallelogram-quadratic-map"),
                DeclarationHandle.Create("D5/S3/QuadraticForms/ParallelogramConstruction.ofParallelogram"),
                H("An integer quadratic map from the parallelogram law"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(
                    Paragraph(Text("For additive commutative groups M and N with injective doubling on N, a function f satisfying f(x + y) + f(x - y) = 2f(x) + 2f(y) determines an integer quadratic map with underlying function f and companion polarization f(x + y) - f(x) - f(y).")),
                    Paragraph(Text("The construction derives the value at zero, evenness, integer quadratic scaling and the three-variable polarization identity. The latter gives biadditivity. Injective doubling permits cancellation; without it a constant nonzero function on a group of exponent two can satisfy the parallelogram law and fail the required zero identity."))),
                DescribeRole.Definition),
            new DocumentBlock.Section(
                H("Application: the complete C133 scalar split criterion"),
                Blocks(
                    Paragraph(Text("Let V be any real Hausdorff topological vector space, with its given topology. Let q: V → [0, infinity) be continuous, q(0)=0, and q(v)=0 imply v=0. Let U: V → V be any real-linear endomorphism. Set D=I+U+U² and A_n=U+nD for every natural n, including zero. The same q, U and vector space are used for all vectors and all n. No continuity, invertibility, periodicity or isometry of U is assumed; no norm, bilinear form, evenness, homogeneity, convexity, finite dimension or completeness is supplied.")),
                    Paragraph(Text("The scalar split criterion is q((f+A_n g)/√2)+q((f−A_n g)/√2) ≤ q(f)+q(g) for every f,g in V and every natural n, without a common finite upper bound on n. It is equivalent to existence of a unique symmetric positive-definite real bilinear form B satisfying B(v,v)=q(v), B(Uf,Ug)=B(f,g), and D=0. The form B is jointly continuous on the original V × V, and the recovered length v ↦ √B(v,v) is continuous on the original V. The nonnegative real codomain may be represented by a real-valued q with an explicit nonnegativity hypothesis: the inclusion of the nonnegative reals into the reals preserves and reflects the topology, zero, sums and order, so it preserves exactly the source hypotheses and split inequality.")),
                    Paragraph(Text("Write a=1/√2. Substitution g=0 gives 2q(av) ≤ q(v). Applying this twice gives q(v/2) ≤ q(v)/4. Monotone.le_iterate_comp_of_le, with observation q, vector map v ↦ v/2 and comparison map t ↦ t/4, supplies q(2^(−m)v) ≤ 4^(−m)q(v) for every natural m; smul_iterate_apply and mul_left_iterate_apply identify the two iterates. This uses the actual one-step consequence of the split criterion, without assuming scalar homogeneity of q.")),
                    Paragraph(Text("For fixed g,n put v=A_n g. The split inequality at f=v gives q(√2 v) ≤ q(v)+q(g), since the other summand is q(0). The first bound, applied to √2 v, gives 2q(v) ≤ q(√2 v). Hence q(A_n g) ≤ q(g) for every n. Taking n=2^m and applying the iterated half-scale inequality to A_(2^m)g gives 0 ≤ q(Dg+2^(−m)Ug) ≤ 4^(−m)q(g). This is where the unbounded natural-number quantifier is used.")),
                    Paragraph(Text("The geometric sequence 2^(−m) tends to zero. Continuous scalar multiplication and addition in the original topology give Dg+2^(−m)Ug → Dg; this involves only the fixed vector Ug and does not use continuity of U. The upper geometric bound tends to zero, so squeeze_zero gives q(Dg+2^(−m)Ug) → 0. Continuity of q gives convergence of the same real sequence to q(Dg). Uniqueness of limits and faithfulness give Dg=0 for every g. The polynomial identity (U−I)(I+U+U²)=U³−I then gives U³=I.")),
                    Paragraph(Text("The n=0 bound is q(Ug) ≤ q(g). Applying it around the three-step cycle yields q(g) ≤ q(U²g) ≤ q(Ug) ≤ q(g), hence q(Ug)=q(g). Also U is surjective, with preimage U²g for g. Substituting h=Ug therefore gives F(H(f,h)) ≤ F(f,h), where F(f,h)=q(f)+q(h) and H(f,h)=(a(f+h),a(f−h)). Since a²=1/2, H²=I. Applying the same inequality at H(f,h) proves equality. Setting h=0 gives 2q(av)=q(v); using that equality on f+h and f−h gives q(f+h)+q(f−h)=2q(f)+2q(h).")),
                    Paragraph(Text("Apply TauCeti.QuadraticMap.ofParallelogram with M=V as an additive group, N=the reals, f=q, and injectivity of doubling in the real codomain. Its underlying function is q; no replacement of the original topology is involved. QuadraticMap.polar_add_left, polar_comm and polar_self show that B(f,h)=(q(f+h)−q(f)−q(h))/2 is symmetric, additive in each argument and satisfies B(f,f)=q(f). The parallelogram identity identifies this formula with the source polarization (q(f+h)−q(f−h))/4.")),
                    Paragraph(Text("For fixed h the displayed expression for B(f,h) is continuous in the original topology. Apply map_real_smul to this continuous additive map; symmetry gives real linearity in the other argument. The same expression gives joint continuity directly by composition with addition and the two coordinate projections. Nonnegativity and faithfulness of q give positive definiteness, including the zero vector space. Continuity of the real square root gives continuity of v ↦ √B(v,v). Since U is linear and q∘U=q, polarization gives B(Uf,Uh)=B(f,h).")),
                    Paragraph(Text("For uniqueness, two symmetric real bilinear forms with the same diagonal q have the same quadratic map. QuadraticMap.associated_left_inverse recovers each form from that diagonal, so they coincide. Conversely, suppose B has the stated properties. D=0 gives A_n=U for every n. Real bilinearity, a²=1/2 and B(Ug,Ug)=B(g,g) give B(a(f+Ug),a(f+Ug))+B(a(f−Ug),a(f−Ug))=B(f,f)+B(g,g). Replacing diagonal values by q proves the original split criterion with equality for every f,g,n.")),
                    Paragraph(Text("This is the complete conditional application in Theorem 2.1 of the C133 scalar-closure continuation, using the existing integer quadratic-map construction and the stated Mathlib iteration, limit and continuous-additive-map results. It adds no named mathematical declaration. The original topology need not equal the recovered norm topology; continuity of U in the original topology is not a conclusion. A finite menu of n is insufficient for the limit step. Physical satisfaction of the split criterion, preparation and operation supply, complete event effects, process kernels, composite systems and physical time remain separate source conditions. The application does not cover the later complex-geometry, finite-menu countermodel or effect-representation results.")))))));
}
